export const ALL_WORDS_UK = [
  ...WORDS_DB_UK.easy.map(i => i.word),
  ...WORDS_DB_UK.medium.map(i => i.word),
  ...WORDS_DB_UK.hard.map(i => i.word),
  ...WORDS_DB_UK.ultraHard.map(i => i.word)
];

export function getDailyWordUk(targetDate = getNYTDate()) {
  const epoch = new Date(2024, 0, 1);
  const diff = targetDate - epoch;
  const oneDay = 1000 * 60 * 60 * 24;
  const index = Math.floor(diff / oneDay);
  
  const difficulties = ['Easy', 'Medium', 'Hard', 'Ultra-Hard'];
  const dbKeys = ['easy', 'medium', 'hard', 'ultraHard'];
  const difficulty = difficulties[index % 4];
  const dbKey = dbKeys[index % 4];
  
  const list = WORDS_DB_UK[dbKey];
  const wordIndex = Math.floor(index / 4) % list.length;
  
  return { ...list[wordIndex], difficulty, dayNumber: index + 1 };
}
